```javascript
import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Configuration
  const PLATE_WIDTH = 1.9;
  const PLATE_HEIGHT = 1.2;
  const PLATE_PITCH = 1.5;
  const NUM_PLATES = 6;
  const COLUMN_OFFSET_X = 0.9;
  const BEVEL_WIDTH = 0.03;
  const ACCENT_WIDTH = 0.03;
  const ACCENT_EMISSIVE = 1.4;
  const FOCUS_SCALE_MAX = 1.06;
  const FOCUS_SCALE_DURATION = 350;
  const SETTLE_DURATION = 900;
  const INERTIA_DAMPING = 0.12;
  const SCROLL_SENSITIVITY = 1.5;

  // Load texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);

  // Colors
  const colors = config.colors || {};
  const colorInk = new THREE.Color(colors.ink || '#16161d');
  const colorAccent = new THREE.Color(colors.accent || '#ff2a38');
  const colorPaper = new THREE.Color(colors.paper || '#e8ecf2');

  // Column group (animated on scroll)
  const columnGroup = new THREE.Group();
  columnGroup.position.x = COLUMN_OFFSET_X;
  group.add(columnGroup);

  // Create 6 plates
  const plates = [];
  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  for (let i = 0; i < NUM_PLATES; i++) {
    const yPos = i * PLATE_PITCH - (NUM_PLATES - 1) * PLATE_PITCH / 2;

    const plateGroup = new THREE.Group();
    plateGroup.position.y = yPos;
    columnGroup.add(plateGroup);

    // Image plate
    const plateMat = new THREE.MeshStandardMaterial({
      map: imageTexture,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });
    const plateMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(PLATE_WIDTH, PLATE_HEIGHT),
      plateMat
    );
    plateGroup.add(plateMesh);

    // Bevel frame
    const bevelMat = new THREE.MeshStandardMaterial({
      color: colorInk,
      roughness: 0.5,
      metalness: 0.5
    });
    const bevelMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(PLATE_WIDTH + 2 * BEVEL_WIDTH, PLATE_HEIGHT + 2 * BEVEL_WIDTH),
      bevelMat
    );
    bevelMesh.position.z = -0.001;
    plateGroup.add(bevelMesh);

    // Accent strip (left edge, lit when focused)
    const accentMat = new THREE.MeshStandardMaterial({
      color: colorAccent,
      emissive: colorAccent,
      emissiveIntensity: 0,
      roughness: 0.5,
      metalness: 0.3
    });
    const accentMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(ACCENT_WIDTH, PLATE_HEIGHT),
      accentMat
    );
    accentMesh.position.set(-(PLATE_WIDTH / 2 + ACCENT_WIDTH / 2), 0, 0.01);
    plateGroup.add(accentMesh);

    // Caption text
    const caption = ctx.fontAtlas.create({
      text: captions[i],
      fontSize: 18,
      fontFamily: 'JetBrains Mono',
      fontWeight: 400,
      letterSpacing: 0.08,
      color: colorPaper
    });
    if (caption.material) {
      caption.material.transparent = true;
      caption.material.opacity = 0;
    }
    caption.position.set(-1.6, 0, 0.05);
    caption.scale.set(0.01, 0.01, 1);
    plateGroup.add(caption);

    plates.push({
      group: plateGroup,
      accent: accentMesh,
      caption: caption,
      worldY: yPos
    });
  }

  // Headline (pinned to scene)
  const headline = ctx.fontAtlas.create({
    text: 'Inside the atelier',
    fontSize: 68,
    fontFamily: 'Lora',
    fontWeight: 600,
    letterSpacing: -0.005,
    color: colorPaper
  });
  if (headline.material) headline.material.transparent = true;
  headline.position.set(-1.6, 1.9, 0.05);
  headline.scale.set(0.01, 0.01, 1);
  group.add(headline);

  // Scroll state
  const state = {
    offsetY: 0,
    velocity: 0,
    settlingTimeline: null,
    rafIds: []
  };

  function getFocusedIndex() {
    let focusedIdx = 0;
    let minDistance = Infinity;

    plates.forEach((plate, idx) => {
      const plateCenterWorldY = plate.worldY - state.offsetY;
      const distance = Math.abs(plateCenterWorldY);
      if (distance < minDistance) {
        minDistance = distance;
        focusedIdx = idx;
      }
    });

    return focusedIdx;
  }

  function updateFocusStates() {
    const focusedIdx = getFocusedIndex();

    plates.forEach((plate, idx) => {
      const isFocused = idx === focusedIdx;

      gsap.to(plate.group.scale, {
        x: isFocused ? FOCUS_SCALE_MAX : 1,
        y: isFocused ? FOCUS_SCALE_MAX : 1,
        duration: FOCUS_SCALE_DURATION / 1000,
        ease: 'power2.out',
        overwrite: 'auto'
      });

      gsap.to(plate.accent.material, {
        emissiveIntensity: isFocused ? ACCENT_EMISSIVE : 0,
        duration: 0.3,
        overwrite: 'auto'
      });

      if (plate.caption.material) {
        gsap.to(plate.caption.material, {
          opacity: isFocused ? 1 : 0,
          duration: 0.3,
          overwrite: 'auto'
        });
      }
    });
  }

  function animateInertia() {
    const raf = requestAnimationFrame(() => {
      if (Math.abs(state.velocity) < 0.001) {
        // Apply weighted-settle
        if (state.settlingTimeline) state.settlingTimeline.kill();
        state.settlingTimeline = gsap.timeline();
        state.settlingTimeline.to(state, {
          offsetY: Math.round(state.offsetY / PLATE_PITCH) * PLATE_PITCH,
          duration: SETTLE_DURATION / 1000,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          onUpdate: () => {
            columnGroup.position.y = -state.offsetY;
            updateFocusStates();
          }
        });
        return;
      }

      state.velocity *= (1 - INERTIA_DAMPING);
      state.offsetY += state.velocity;
      columnGroup.position.y = -state.offsetY;
      updateFocusStates();
      animateInertia();
    });

    state.rafIds.push(raf);
  }

  function onWheel(event) {
    // Cancel ongoing inertia/settle
    state.rafIds.forEach(id => cancelAnimationFrame(id));
    state.rafIds = [];
    if (state.settlingTimeline) {
      state.settlingTimeline.kill();
      state.settlingTimeline = null;
    }

    // Apply immediate scroll momentum
    state.velocity = -(event.deltaY || 0) * SCROLL_SENSITIVITY;
    state.offsetY += state.velocity;
    columnGroup.position.y = -state.offsetY;
    updateFocusStates();

    // Schedule inertia phase
    setTimeout(() => {
      animateInertia();
    }, 50);
  }

  group.userData.handlers = {
    wheel: onWheel
  };

  // Apply fly-through cinematic primitive
  if (ctx.primitives && ctx.primitives['fly-through']) {
    ctx.primitives['fly-through'](group, { depthUnits: 2.5 });
  }

  // Cleanup
  group.userData.cleanup = function() {
    state.rafIds.forEach(id => cancelAnimationFrame(id));
    if (state.settlingTimeline) state.settlingTimeline.kill();

    gsap.killTweensOf(state);
    plates.forEach(p => {
      gsap.killTweensOf(p.group.scale);
      gsap.killTweensOf(p.accent.material);
      if (p.caption.material) gsap.killTweensOf(p.caption.material);

      p.group.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
      if (p.caption.geometry) p.caption.geometry.dispose();
      if (p.caption.material) p.caption.material.dispose();
    });

    if (headline.geometry) headline.geometry.dispose();
    if (headline.material) headline.material.dispose();
    imageTexture.dispose();
  };

  return group;
}
